BEGIN;
DO $$
DECLARE
  v_subject_id UUID;
  v_topic_id UUID;
  v_test_id BIGINT;
BEGIN
  SELECT id INTO v_subject_id FROM test_subjects WHERE name ILIKE '%cardio%' ORDER BY id LIMIT 1;
  IF v_subject_id IS NULL THEN
    INSERT INTO test_subjects (name, description) VALUES ('Cardiovascular System', 'Cardiovascular notes') RETURNING id INTO v_subject_id;
  END IF;
  SELECT id INTO v_topic_id FROM test_topics WHERE name = 'Cardiac Biomarkers' ORDER BY (SELECT COUNT(*) FROM test_questions q WHERE q.topic_id = test_topics.id) DESC, created_at ASC LIMIT 1;
  IF v_topic_id IS NULL THEN
    INSERT INTO test_topics (subject_id, name, description, status) VALUES (v_subject_id, 'Cardiac Biomarkers', 'Troponin CK-MB BNP and myoglobin interpretation', 'published') RETURNING id INTO v_topic_id;
  END IF;
  SELECT id INTO v_test_id FROM tests WHERE is_active = true ORDER BY id LIMIT 1;
  IF v_test_id IS NULL THEN
    INSERT INTO tests (test_name, system_category, description, is_active)
    VALUES ('Cardiovascular System - Cardiac Biomarkers (Generated)', 'Cardiovascular System', 'Auto-generated NCLEX question set', true)
    RETURNING id INTO v_test_id;
  END IF;
  DELETE FROM test_questions WHERE topic_id = v_topic_id AND category = 'Cardiac Biomarkers - NCLEX';
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Cardiac Biomarkers note, which statement about "Biomarker purpose" is most accurate?', 'According to the Cardiac Biomarkers note, which statement about "Biomarker purpose" is most accurate?', '[{"id": "a", "text": "Biomarkers rise when cardiac cells are damaged."}, {"id": "b", "text": "Biomarkers only diagnose pulmonary embolism."}, {"id": "c", "text": "CK-MM is most cardiac-specific marker."}, {"id": "d", "text": "Cardiac injury does not alter biomarker levels."}]'::jsonb, '["a"]'::jsonb, 'Correct because Cardiac biomarkers are blood proteins released after cardiac cell injury and are used for MI/HF diagnosis and stress assessment. Use biomarkers with clinical context to confirm or exclude acute cardiac injury.', 'Cardiac Biomarkers - NCLEX', false, 1, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Serial testing principle" in Cardiac Biomarkers. Which statement is correct?', 'The nurse is reviewing "Serial testing principle" in Cardiac Biomarkers. Which statement is correct?', '[{"id": "a", "text": "CK-BB comes from ventricular myocardium."}, {"id": "b", "text": "Serial testing is unnecessary in acute chest pain."}, {"id": "c", "text": "Serial rechecks are unnecessary when first value is borderline."}, {"id": "d", "text": "Single value alone is insufficient for MI confirmation."}]'::jsonb, '["d"]'::jsonb, 'Correct because Serial values every 3–6 hours are needed, and a rise-and-fall pattern supports MI rather than one isolated elevation. Trend interpretation is safer than single-point interpretation.', 'Cardiac Biomarkers - NCLEX', false, 2, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Troponin priority" in Cardiac Biomarkers?', 'Which clinical judgment is most accurate regarding "Troponin priority" in Cardiac Biomarkers?', '[{"id": "a", "text": "BNP is unrelated to ventricular stretch."}, {"id": "b", "text": "Troponin has highest NCLEX priority in this section."}, {"id": "c", "text": "Myoglobin is more specific than troponin."}, {"id": "d", "text": "Serial rechecks are unnecessary when first value is borderline."}]'::jsonb, '["b"]'::jsonb, 'Correct because Troponin is the most specific and sensitive biomarker for MI and is the gold standard. Prioritize troponin trend review in suspected ACS workflows.', 'Cardiac Biomarkers - NCLEX', false, 3, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Troponin I kinetics" in Cardiac Biomarkers?', 'In rapid prioritization, which statement is most consistent with "Troponin I kinetics" in Cardiac Biomarkers?', '[{"id": "a", "text": "Troponin I normalizes within 12 hours."}, {"id": "b", "text": "CK-MB remains elevated for 14 days."}, {"id": "c", "text": "CK-BB is dominant in healthy blood."}, {"id": "d", "text": "Troponin I can stay elevated for 7–10 days."}]'::jsonb, '["d"]'::jsonb, 'Correct because Troponin I normal is <0.04 ng/mL, rises 3–6h, peaks 12–24h, normalizes in 7–10 days. Use timing to detect delayed presentations and avoid false reassurance early.', 'Cardiac Biomarkers - NCLEX', false, 4, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Troponin T kinetics" in Cardiac Biomarkers would the nurse recognize as correct?', 'Which conclusion about "Troponin T kinetics" in Cardiac Biomarkers would the nurse recognize as correct?', '[{"id": "a", "text": "Troponin T has no normal reference."}, {"id": "b", "text": "CK-MM is most cardiac-specific marker."}, {"id": "c", "text": "Rise/peak times mirror early troponin kinetics."}, {"id": "d", "text": "BNP confirms MI infarct size directly."}]'::jsonb, '["c"]'::jsonb, 'Correct because Troponin T normal is <0.01 ng/mL, rises 3–6h, peaks 12–24h, and normalizes over 10–14 days. Recognize prolonged elevation window for recent MI detection.', 'Cardiac Biomarkers - NCLEX', false, 5, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Cardiac Biomarkers note, which statement about "hsTnT utility" is most accurate?', 'According to the Cardiac Biomarkers note, which statement about "hsTnT utility" is most accurate?', '[{"id": "a", "text": "Useful in early subtle MI detection."}, {"id": "b", "text": "CK-BB is preferred biomarker for MI."}, {"id": "c", "text": "hsTnT is less sensitive than CK-MB."}, {"id": "d", "text": "BNP is the most specific MI marker."}]'::jsonb, '["a"]'::jsonb, 'Correct because High-sensitivity Troponin T can detect smaller myocardial infarctions. Interpret small dynamic changes carefully in early injury.', 'Cardiac Biomarkers - NCLEX', false, 6, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "CK isoform composition" in Cardiac Biomarkers. Which statement is correct?', 'The nurse is reviewing "CK isoform composition" in Cardiac Biomarkers. Which statement is correct?', '[{"id": "a", "text": "CK-BB is minimal in routine blood profile here."}, {"id": "b", "text": "CK-BB comes from ventricular myocardium."}, {"id": "c", "text": "CK-BB is dominant in healthy blood."}, {"id": "d", "text": "NT-proBNP has shorter half-life than BNP."}]'::jsonb, '["a"]'::jsonb, 'Correct because CK-MM is 96–100%, CK-MB is 0–5%, and CK-BB is about 0% in normal distribution listed. Know isoform proportions to avoid misattributing skeletal injury as MI.', 'Cardiac Biomarkers - NCLEX', false, 7, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "CK-MB timeline/use" in Cardiac Biomarkers?', 'Which clinical judgment is most accurate regarding "CK-MB timeline/use" in Cardiac Biomarkers?', '[{"id": "a", "text": "CK-MB normalizes faster than troponin."}, {"id": "b", "text": "Myoglobin rises after troponin peak."}, {"id": "c", "text": "BNP rises only from skeletal injury."}, {"id": "d", "text": "CK-MB remains elevated for 14 days."}]'::jsonb, '["a"]'::jsonb, 'Correct because CK-MB rises 4–6h, peaks 18–24h, normalizes 48–72h, and is useful for MI and re-infarction detection. Use CK-MB especially when looking for reinfarction after initial event.', 'Cardiac Biomarkers - NCLEX', false, 8, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "CK-MM limitation" in Cardiac Biomarkers?', 'In rapid prioritization, which statement is most consistent with "CK-MM limitation" in Cardiac Biomarkers?', '[{"id": "a", "text": "Avoid diagnosing MI from CK-MM elevation alone."}, {"id": "b", "text": "BNP confirms MI infarct size directly."}, {"id": "c", "text": "CK-MM is most cardiac-specific marker."}, {"id": "d", "text": "Myoglobin is highly cardiac-specific."}]'::jsonb, '["a"]'::jsonb, 'Correct because CK-MM reflects skeletal muscle injury such as rhabdomyolysis and is not cardiac-specific. Avoid diagnosing MI from CK-MM elevation alone.', 'Cardiac Biomarkers - NCLEX', false, 9, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "CK-BB limitation" in Cardiac Biomarkers would the nurse recognize as correct?', 'Which conclusion about "CK-BB limitation" in Cardiac Biomarkers would the nurse recognize as correct?', '[{"id": "a", "text": "BNP confirms MI infarct size directly."}, {"id": "b", "text": "CK-BB comes from ventricular myocardium."}, {"id": "c", "text": "CK-BB is preferred biomarker for MI."}, {"id": "d", "text": "CK-BB is linked to brain/smooth muscle."}]'::jsonb, '["d"]'::jsonb, 'Correct because CK-BB is associated with brain/smooth muscle injury and is not used for cardiac monitoring. Keep CK-BB out of MI-focused biomarker decisions.', 'Cardiac Biomarkers - NCLEX', false, 10, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Cardiac Biomarkers note, which statement about "BNP physiology" is most accurate?', 'According to the Cardiac Biomarkers note, which statement about "BNP physiology" is most accurate?', '[{"id": "a", "text": "BNP is unrelated to ventricular stretch."}, {"id": "b", "text": "Ventricular stretch triggers BNP release."}, {"id": "c", "text": "Normal creatinine excludes dehydration."}, {"id": "d", "text": "High BUN with normal creatinine proves MI."}]'::jsonb, '["b"]'::jsonb, 'Correct because BNP is released from ventricular myocytes when stretched by volume overload. Interpret BNP as volume-stress signal rather than infarction specificity.', 'Cardiac Biomarkers - NCLEX', false, 11, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "BNP ranges" in Cardiac Biomarkers. Which statement is correct?', 'The nurse is reviewing "BNP ranges" in Cardiac Biomarkers. Which statement is correct?', '[{"id": "a", "text": "BNP <20 defines severe HF."}, {"id": "b", "text": "BUN/Cr are unrelated to hemodynamics."}, {"id": "c", "text": "Myoglobin rises after troponin peak."}, {"id": "d", "text": ">400 suggests likely HF exacerbation."}]'::jsonb, '["d"]'::jsonb, 'Correct because BNP normal is <100 pg/mL; 100–400 possible HF; >400 likely HF exacerbation. Use BNP strata to grade heart-failure likelihood and urgency.', 'Cardiac Biomarkers - NCLEX', false, 12, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "BNP clinical use" in Cardiac Biomarkers?', 'Which clinical judgment is most accurate regarding "BNP clinical use" in Cardiac Biomarkers?', '[{"id": "a", "text": "Lactate <0.2 is the shock threshold."}, {"id": "b", "text": "Higher BNP correlates with worse prognosis."}, {"id": "c", "text": "BNP confirms MI infarct size directly."}, {"id": "d", "text": "Myoglobin is highly cardiac-specific."}]'::jsonb, '["b"]'::jsonb, 'Correct because BNP helps differentiate cardiac from pulmonary dyspnea, guides diuresis/discharge, and higher BNP suggests worse prognosis. Apply BNP trends to dyspnea triage and HF trajectory planning.', 'Cardiac Biomarkers - NCLEX', false, 13, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "BNP not MI marker" in Cardiac Biomarkers?', 'In rapid prioritization, which statement is most consistent with "BNP not MI marker" in Cardiac Biomarkers?', '[{"id": "a", "text": "BNP is the most specific MI marker."}, {"id": "b", "text": "Myoglobin is highly cardiac-specific."}, {"id": "c", "text": "LDL >160 is optimal in high-risk."}, {"id": "d", "text": "Troponin remains MI marker priority."}]'::jsonb, '["d"]'::jsonb, 'Correct because The note explicitly states BNP does not indicate MI; it indicates fluid overload/heart failure context. Do not substitute BNP for troponin in ACS diagnosis.', 'Cardiac Biomarkers - NCLEX', false, 14, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "NT-proBNP reference" in Cardiac Biomarkers would the nurse recognize as correct?', 'Which conclusion about "NT-proBNP reference" in Cardiac Biomarkers would the nurse recognize as correct?', '[{"id": "a", "text": "NT-proBNP has shorter half-life than BNP."}, {"id": "b", "text": "Serial rechecks are unnecessary when first value is borderline."}, {"id": "c", "text": "BNP replaces troponin for MI confirmation."}, {"id": "d", "text": "NT-proBNP interpretation differs from BNP thresholds."}]'::jsonb, '["d"]'::jsonb, 'Correct because NT-proBNP normal is listed as <300 pg/mL and has longer half-life. Account for assay type when interpreting natriuretic peptide results.', 'Cardiac Biomarkers - NCLEX', false, 15, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Cardiac Biomarkers note, which statement about "Myoglobin kinetics" is most accurate?', 'According to the Cardiac Biomarkers note, which statement about "Myoglobin kinetics" is most accurate?', '[{"id": "a", "text": "Normal creatinine excludes dehydration."}, {"id": "b", "text": "High BUN with normal creatinine proves MI."}, {"id": "c", "text": "Myoglobin rises after troponin peak."}, {"id": "d", "text": "Normalization occurs by about 24 hours."}]'::jsonb, '["d"]'::jsonb, 'Correct because Myoglobin rises first at 1–3h after MI but normalizes quickly within 24h. Use for very early phase support, then rely on specific markers.', 'Cardiac Biomarkers - NCLEX', false, 16, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Myoglobin limitation/use" in Cardiac Biomarkers. Which statement is correct?', 'The nurse is reviewing "Myoglobin limitation/use" in Cardiac Biomarkers. Which statement is correct?', '[{"id": "a", "text": "Serial testing is unnecessary in acute chest pain."}, {"id": "b", "text": "Myoglobin is highly cardiac-specific."}, {"id": "c", "text": "Myoglobin comes from skeletal and cardiac muscle."}, {"id": "d", "text": "Renal perfusion is unaffected by cardiac output."}]'::jsonb, '["c"]'::jsonb, 'Correct because Myoglobin is not cardiac-specific and is used mainly for early rule-out when normal at around 3h. Avoid overcalling MI from isolated myoglobin elevation.', 'Cardiac Biomarkers - NCLEX', false, 17, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Timeline comparison" in Cardiac Biomarkers?', 'Which clinical judgment is most accurate regarding "Timeline comparison" in Cardiac Biomarkers?', '[{"id": "a", "text": "Troponin clears before CK-MB."}, {"id": "b", "text": "Serial rechecks are unnecessary when first value is borderline."}, {"id": "c", "text": "Myoglobin is more specific than troponin."}, {"id": "d", "text": "Choose marker by time-from-onset and diagnostic objective."}]'::jsonb, '["d"]'::jsonb, 'Correct because Timeline summary: myoglobin earliest/shortest, CK-MB intermediate, troponin longest duration. Choose marker by time-from-onset and diagnostic objective.', 'Cardiac Biomarkers - NCLEX', false, 18, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "BUN/creatinine interpretation" in Cardiac Biomarkers?', 'In rapid prioritization, which statement is most consistent with "BUN/creatinine interpretation" in Cardiac Biomarkers?', '[{"id": "a", "text": "High BUN with normal creatinine proves MI."}, {"id": "b", "text": "Normal creatinine excludes dehydration."}, {"id": "c", "text": "Serial rechecks are unnecessary when first value is borderline."}, {"id": "d", "text": "High BUN + high creatinine suggests renal impairment."}]'::jsonb, '["d"]'::jsonb, 'Correct because BUN 7–20 and creatinine 0.6–1.2 are listed normal; high BUN with normal creatinine suggests dehydration, while both high suggest renal impairment. Use renal trends to separate prerenal dehydration from intrinsic decline.', 'Cardiac Biomarkers - NCLEX', false, 19, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Low-output renal effect" in Cardiac Biomarkers would the nurse recognize as correct?', 'Which conclusion about "Low-output renal effect" in Cardiac Biomarkers would the nurse recognize as correct?', '[{"id": "a", "text": "Renal perfusion is unaffected by cardiac output."}, {"id": "b", "text": "Low cardiac output can impair renal perfusion."}, {"id": "c", "text": "Biomarkers only diagnose pulmonary embolism."}, {"id": "d", "text": "BNP replaces troponin for MI confirmation."}]'::jsonb, '["b"]'::jsonb, 'Correct because Reduced cardiac output can increase BUN/creatinine due to renal hypoperfusion. Treat perfusion deficits to protect kidney function.', 'Cardiac Biomarkers - NCLEX', false, 20, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Cardiac Biomarkers note, which statement about "Lactate and ABG significance" is most accurate?', 'According to the Cardiac Biomarkers note, which statement about "Lactate and ABG significance" is most accurate?', '[{"id": "a", "text": "One elevated value always confirms MI."}, {"id": "b", "text": "Lactate <0.2 is the shock threshold."}, {"id": "c", "text": "Metabolic acidosis can occur in shock/MI."}, {"id": "d", "text": "Biomarkers only diagnose pulmonary embolism."}]'::jsonb, '["c"]'::jsonb, 'Correct because Shock/MI may show metabolic acidosis; lactate >2 mmol/L indicates tissue hypoperfusion and helps gauge shock severity. Escalate perfusion support when lactate and acidosis worsen.', 'Cardiac Biomarkers - NCLEX', false, 21, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Lipid panel targets" in Cardiac Biomarkers. Which statement is correct?', 'The nurse is reviewing "Lipid panel targets" in Cardiac Biomarkers. Which statement is correct?', '[{"id": "a", "text": "Incorporate lipid targets into long-term post-ACS risk reduction."}, {"id": "b", "text": "LDL >160 is optimal in high-risk."}, {"id": "c", "text": "Single-point interpretation is always definitive regardless trend direction."}, {"id": "d", "text": "Serial rechecks are unnecessary when first value is borderline."}]'::jsonb, '["a"]'::jsonb, 'Correct because Desired lipids listed are total cholesterol <200, LDL <70 in high-risk patients, and HDL >60 as protective. Incorporate lipid targets into long-term post-ACS risk reduction.', 'Cardiac Biomarkers - NCLEX', false, 22, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "NCLEX synthesis" in Cardiac Biomarkers?', 'Which clinical judgment is most accurate regarding "NCLEX synthesis" in Cardiac Biomarkers?', '[{"id": "a", "text": "Troponin is top MI marker in NCLEX summary."}, {"id": "b", "text": "BNP replaces troponin for MI confirmation."}, {"id": "c", "text": "Troponin I normalizes within 12 hours."}, {"id": "d", "text": "Myoglobin is more specific than troponin."}]'::jsonb, '["a"]'::jsonb, 'Correct because NCLEX summary: Troponin is gold standard and longest-lasting, CK-MB best for reinfarction, BNP for HF dyspnea differentiation, myoglobin earliest but nonspecific. Match biomarker selection to the clinical question (diagnosis timing vs HF vs reinfarction).', 'Cardiac Biomarkers - NCLEX', false, 23, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Biomarker purpose" in Cardiac Biomarkers?', 'In rapid prioritization, which statement is most consistent with "Biomarker purpose" in Cardiac Biomarkers?', '[{"id": "a", "text": "Troponin T has no normal reference."}, {"id": "b", "text": "They assess cardiac stress patterns."}, {"id": "c", "text": "Troponin I normalizes within 12 hours."}, {"id": "d", "text": "Biomarkers only diagnose pulmonary embolism."}]'::jsonb, '["b"]'::jsonb, 'Correct because Cardiac biomarkers are blood proteins released after cardiac cell injury and are used for MI/HF diagnosis and stress assessment. Use biomarkers with clinical context to confirm or exclude acute cardiac injury.', 'Cardiac Biomarkers - NCLEX', false, 24, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Serial testing principle" in Cardiac Biomarkers would the nurse recognize as correct?', 'Which conclusion about "Serial testing principle" in Cardiac Biomarkers would the nurse recognize as correct?', '[{"id": "a", "text": "Serial testing is unnecessary in acute chest pain."}, {"id": "b", "text": "Trend interpretation is safer than single-point interpretation."}, {"id": "c", "text": "Single-point interpretation is always definitive regardless trend direction."}, {"id": "d", "text": "Serial rechecks are unnecessary when first value is borderline."}]'::jsonb, '["b"]'::jsonb, 'Correct because Serial values every 3–6 hours are needed, and a rise-and-fall pattern supports MI rather than one isolated elevation. Trend interpretation is safer than single-point interpretation.', 'Cardiac Biomarkers - NCLEX', false, 25, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Cardiac Biomarkers note, which statement about "Troponin priority" is most accurate?', 'According to the Cardiac Biomarkers note, which statement about "Troponin priority" is most accurate?', '[{"id": "a", "text": "BNP is unrelated to ventricular stretch."}, {"id": "b", "text": "Myoglobin is more specific than troponin."}, {"id": "c", "text": "Serial rechecks are unnecessary when first value is borderline."}, {"id": "d", "text": "Troponin is both highly sensitive and specific in note."}]'::jsonb, '["d"]'::jsonb, 'Correct because Troponin is the most specific and sensitive biomarker for MI and is the gold standard. Prioritize troponin trend review in suspected ACS workflows.', 'Cardiac Biomarkers - NCLEX', false, 26, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Troponin I kinetics" in Cardiac Biomarkers. Which statement is correct?', 'The nurse is reviewing "Troponin I kinetics" in Cardiac Biomarkers. Which statement is correct?', '[{"id": "a", "text": "Single-point interpretation is always definitive regardless trend direction."}, {"id": "b", "text": "Serial rechecks are unnecessary when first value is borderline."}, {"id": "c", "text": "Troponin I normalizes within 12 hours."}, {"id": "d", "text": "Use timing to detect delayed presentations and avoid false reassurance early."}]'::jsonb, '["d"]'::jsonb, 'Correct because Troponin I normal is <0.04 ng/mL, rises 3–6h, peaks 12–24h, normalizes in 7–10 days. Use timing to detect delayed presentations and avoid false reassurance early.', 'Cardiac Biomarkers - NCLEX', false, 27, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Troponin T kinetics" in Cardiac Biomarkers?', 'Which clinical judgment is most accurate regarding "Troponin T kinetics" in Cardiac Biomarkers?', '[{"id": "a", "text": "Serial rechecks are unnecessary when first value is borderline."}, {"id": "b", "text": "Single-point interpretation is always definitive regardless trend direction."}, {"id": "c", "text": "Recognize prolonged elevation window for recent MI detection."}, {"id": "d", "text": "Troponin T has no normal reference."}]'::jsonb, '["c"]'::jsonb, 'Correct because Troponin T normal is <0.01 ng/mL, rises 3–6h, peaks 12–24h, and normalizes over 10–14 days. Recognize prolonged elevation window for recent MI detection.', 'Cardiac Biomarkers - NCLEX', false, 28, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "hsTnT utility" in Cardiac Biomarkers?', 'In rapid prioritization, which statement is most consistent with "hsTnT utility" in Cardiac Biomarkers?', '[{"id": "a", "text": "hsTnT is used only for heart failure."}, {"id": "b", "text": "Single-point interpretation is always definitive regardless trend direction."}, {"id": "c", "text": "Interpret small dynamic changes carefully in early injury."}, {"id": "d", "text": "Serial rechecks are unnecessary when first value is borderline."}]'::jsonb, '["c"]'::jsonb, 'Correct because High-sensitivity Troponin T can detect smaller myocardial infarctions. Interpret small dynamic changes carefully in early injury.', 'Cardiac Biomarkers - NCLEX', false, 29, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "CK isoform composition" in Cardiac Biomarkers would the nurse recognize as correct?', 'Which conclusion about "CK isoform composition" in Cardiac Biomarkers would the nurse recognize as correct?', '[{"id": "a", "text": "Know isoform proportions to avoid misattributing skeletal injury as MI."}, {"id": "b", "text": "CK-BB is dominant in healthy blood."}, {"id": "c", "text": "Serial rechecks are unnecessary when first value is borderline."}, {"id": "d", "text": "Single-point interpretation is always definitive regardless trend direction."}]'::jsonb, '["a"]'::jsonb, 'Correct because CK-MM is 96–100%, CK-MB is 0–5%, and CK-BB is about 0% in normal distribution listed. Know isoform proportions to avoid misattributing skeletal injury as MI.', 'Cardiac Biomarkers - NCLEX', false, 30, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Cardiac Biomarkers note, which statement about "CK-MB timeline/use" is most accurate?', 'According to the Cardiac Biomarkers note, which statement about "CK-MB timeline/use" is most accurate?', '[{"id": "a", "text": "CK-MB is useful for reinfarction detection."}, {"id": "b", "text": "BNP is unrelated to ventricular stretch."}, {"id": "c", "text": "CK-MB remains elevated for 14 days."}, {"id": "d", "text": "BNP rises only from skeletal injury."}]'::jsonb, '["a"]'::jsonb, 'Correct because CK-MB rises 4–6h, peaks 18–24h, normalizes 48–72h, and is useful for MI and re-infarction detection. Use CK-MB especially when looking for reinfarction after initial event.', 'Cardiac Biomarkers - NCLEX', false, 31, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "CK-MM limitation" in Cardiac Biomarkers. Which statement is correct?', 'The nurse is reviewing "CK-MM limitation" in Cardiac Biomarkers. Which statement is correct?', '[{"id": "a", "text": "CK-MM reflects skeletal muscle injury such as rhabdomyolysis and is not cardiac-specific."}, {"id": "b", "text": "CK-MM is most cardiac-specific marker."}, {"id": "c", "text": "Serial rechecks are unnecessary when first value is borderline."}, {"id": "d", "text": "Single-point interpretation is always definitive regardless trend direction."}]'::jsonb, '["a"]'::jsonb, 'Correct because CK-MM reflects skeletal muscle injury such as rhabdomyolysis and is not cardiac-specific. Avoid diagnosing MI from CK-MM elevation alone.', 'Cardiac Biomarkers - NCLEX', false, 32, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "CK-BB limitation" in Cardiac Biomarkers?', 'Which clinical judgment is most accurate regarding "CK-BB limitation" in Cardiac Biomarkers?', '[{"id": "a", "text": "CK-BB is not cardiac marker of choice."}, {"id": "b", "text": "CK-BB comes from ventricular myocardium."}, {"id": "c", "text": "BNP confirms MI infarct size directly."}, {"id": "d", "text": "CK-BB is preferred biomarker for MI."}]'::jsonb, '["a"]'::jsonb, 'Correct because CK-BB is associated with brain/smooth muscle injury and is not used for cardiac monitoring. Keep CK-BB out of MI-focused biomarker decisions.', 'Cardiac Biomarkers - NCLEX', false, 33, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "BNP physiology" in Cardiac Biomarkers?', 'In rapid prioritization, which statement is most consistent with "BNP physiology" in Cardiac Biomarkers?', '[{"id": "a", "text": "Interpret BNP as volume-stress signal rather than infarction specificity."}, {"id": "b", "text": "Serial rechecks are unnecessary when first value is borderline."}, {"id": "c", "text": "Single-point interpretation is always definitive regardless trend direction."}, {"id": "d", "text": "BNP is unrelated to ventricular stretch."}]'::jsonb, '["a"]'::jsonb, 'Correct because BNP is released from ventricular myocytes when stretched by volume overload. Interpret BNP as volume-stress signal rather than infarction specificity.', 'Cardiac Biomarkers - NCLEX', false, 34, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "BNP ranges" in Cardiac Biomarkers would the nurse recognize as correct?', 'Which conclusion about "BNP ranges" in Cardiac Biomarkers would the nurse recognize as correct?', '[{"id": "a", "text": "BNP <20 defines severe HF."}, {"id": "b", "text": "Serial rechecks are unnecessary when first value is borderline."}, {"id": "c", "text": "Renal perfusion is unaffected by cardiac output."}, {"id": "d", "text": "Use BNP strata to grade heart-failure likelihood and urgency."}]'::jsonb, '["d"]'::jsonb, 'Correct because BNP normal is <100 pg/mL; 100–400 possible HF; >400 likely HF exacerbation. Use BNP strata to grade heart-failure likelihood and urgency.', 'Cardiac Biomarkers - NCLEX', false, 35, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Cardiac Biomarkers note, which statement about "BNP clinical use" is most accurate?', 'According to the Cardiac Biomarkers note, which statement about "BNP clinical use" is most accurate?', '[{"id": "a", "text": "Myoglobin rises after troponin peak."}, {"id": "b", "text": "BNP confirms MI infarct size directly."}, {"id": "c", "text": "Lactate <0.2 is the shock threshold."}, {"id": "d", "text": "BNP helps guide diuretic and discharge decisions."}]'::jsonb, '["d"]'::jsonb, 'Correct because BNP helps differentiate cardiac from pulmonary dyspnea, guides diuresis/discharge, and higher BNP suggests worse prognosis. Apply BNP trends to dyspnea triage and HF trajectory planning.', 'Cardiac Biomarkers - NCLEX', false, 36, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "BNP not MI marker" in Cardiac Biomarkers. Which statement is correct?', 'The nurse is reviewing "BNP not MI marker" in Cardiac Biomarkers. Which statement is correct?', '[{"id": "a", "text": "Myoglobin is highly cardiac-specific."}, {"id": "b", "text": "LDL >160 is optimal in high-risk."}, {"id": "c", "text": "BNP is the most specific MI marker."}, {"id": "d", "text": "BNP is HF-oriented biomarker in note."}]'::jsonb, '["d"]'::jsonb, 'Correct because The note explicitly states BNP does not indicate MI; it indicates fluid overload/heart failure context. Do not substitute BNP for troponin in ACS diagnosis.', 'Cardiac Biomarkers - NCLEX', false, 37, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "NT-proBNP reference" in Cardiac Biomarkers?', 'Which clinical judgment is most accurate regarding "NT-proBNP reference" in Cardiac Biomarkers?', '[{"id": "a", "text": "Single-point interpretation is always definitive regardless trend direction."}, {"id": "b", "text": "Account for assay type when interpreting natriuretic peptide results."}, {"id": "c", "text": "Serial rechecks are unnecessary when first value is borderline."}, {"id": "d", "text": "NT-proBNP has shorter half-life than BNP."}]'::jsonb, '["b"]'::jsonb, 'Correct because NT-proBNP normal is listed as <300 pg/mL and has longer half-life. Account for assay type when interpreting natriuretic peptide results.', 'Cardiac Biomarkers - NCLEX', false, 38, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Myoglobin kinetics" in Cardiac Biomarkers?', 'In rapid prioritization, which statement is most consistent with "Myoglobin kinetics" in Cardiac Biomarkers?', '[{"id": "a", "text": "BUN/Cr are unrelated to hemodynamics."}, {"id": "b", "text": "Myoglobin rises after troponin peak."}, {"id": "c", "text": "Normalization occurs by about 24 hours."}, {"id": "d", "text": "Normal creatinine excludes dehydration."}]'::jsonb, '["c"]'::jsonb, 'Correct because Myoglobin rises first at 1–3h after MI but normalizes quickly within 24h. Use for very early phase support, then rely on specific markers.', 'Cardiac Biomarkers - NCLEX', false, 39, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Myoglobin limitation/use" in Cardiac Biomarkers would the nurse recognize as correct?', 'Which conclusion about "Myoglobin limitation/use" in Cardiac Biomarkers would the nurse recognize as correct?', '[{"id": "a", "text": "Myoglobin is highly cardiac-specific."}, {"id": "b", "text": "Renal perfusion is unaffected by cardiac output."}, {"id": "c", "text": "Serial testing is unnecessary in acute chest pain."}, {"id": "d", "text": "Normal early myoglobin lowers immediate MI likelihood."}]'::jsonb, '["d"]'::jsonb, 'Correct because Myoglobin is not cardiac-specific and is used mainly for early rule-out when normal at around 3h. Avoid overcalling MI from isolated myoglobin elevation.', 'Cardiac Biomarkers - NCLEX', false, 40, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Cardiac Biomarkers note, which statement about "Timeline comparison" is most accurate?', 'According to the Cardiac Biomarkers note, which statement about "Timeline comparison" is most accurate?', '[{"id": "a", "text": "Troponin clears before CK-MB."}, {"id": "b", "text": "Timeline summary: myoglobin earliest/shortest, CK-MB intermediate, troponin longest duration."}, {"id": "c", "text": "Serial rechecks are unnecessary when first value is borderline."}, {"id": "d", "text": "Single-point interpretation is always definitive regardless trend direction."}]'::jsonb, '["b"]'::jsonb, 'Correct because Timeline summary: myoglobin earliest/shortest, CK-MB intermediate, troponin longest duration. Choose marker by time-from-onset and diagnostic objective.', 'Cardiac Biomarkers - NCLEX', false, 41, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "BUN/creatinine interpretation" in Cardiac Biomarkers. Which statement is correct?', 'The nurse is reviewing "BUN/creatinine interpretation" in Cardiac Biomarkers. Which statement is correct?', '[{"id": "a", "text": "High BUN with normal creatinine proves MI."}, {"id": "b", "text": "Single-point interpretation is always definitive regardless trend direction."}, {"id": "c", "text": "Use renal trends to separate prerenal dehydration from intrinsic decline."}, {"id": "d", "text": "Serial rechecks are unnecessary when first value is borderline."}]'::jsonb, '["c"]'::jsonb, 'Correct because BUN 7–20 and creatinine 0.6–1.2 are listed normal; high BUN with normal creatinine suggests dehydration, while both high suggest renal impairment. Use renal trends to separate prerenal dehydration from intrinsic decline.', 'Cardiac Biomarkers - NCLEX', false, 42, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Low-output renal effect" in Cardiac Biomarkers?', 'Which clinical judgment is most accurate regarding "Low-output renal effect" in Cardiac Biomarkers?', '[{"id": "a", "text": "Renal perfusion is unaffected by cardiac output."}, {"id": "b", "text": "Treat perfusion deficits to protect kidney function."}, {"id": "c", "text": "BNP replaces troponin for MI confirmation."}, {"id": "d", "text": "Cardiac injury does not alter biomarker levels."}]'::jsonb, '["b"]'::jsonb, 'Correct because Reduced cardiac output can increase BUN/creatinine due to renal hypoperfusion. Treat perfusion deficits to protect kidney function.', 'Cardiac Biomarkers - NCLEX', false, 43, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Lactate and ABG significance" in Cardiac Biomarkers?', 'In rapid prioritization, which statement is most consistent with "Lactate and ABG significance" in Cardiac Biomarkers?', '[{"id": "a", "text": "Lactate >2 indicates hypoperfusion in note."}, {"id": "b", "text": "Cardiac injury does not alter biomarker levels."}, {"id": "c", "text": "Lactate <0.2 is the shock threshold."}, {"id": "d", "text": "Biomarkers only diagnose pulmonary embolism."}]'::jsonb, '["a"]'::jsonb, 'Correct because Shock/MI may show metabolic acidosis; lactate >2 mmol/L indicates tissue hypoperfusion and helps gauge shock severity. Escalate perfusion support when lactate and acidosis worsen.', 'Cardiac Biomarkers - NCLEX', false, 44, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Lipid panel targets" in Cardiac Biomarkers would the nurse recognize as correct?', 'Which conclusion about "Lipid panel targets" in Cardiac Biomarkers would the nurse recognize as correct?', '[{"id": "a", "text": "Single-point interpretation is always definitive regardless trend direction."}, {"id": "b", "text": "Incorporate lipid targets into long-term post-ACS risk reduction."}, {"id": "c", "text": "LDL >160 is optimal in high-risk."}, {"id": "d", "text": "Serial rechecks are unnecessary when first value is borderline."}]'::jsonb, '["b"]'::jsonb, 'Correct because Desired lipids listed are total cholesterol <200, LDL <70 in high-risk patients, and HDL >60 as protective. Incorporate lipid targets into long-term post-ACS risk reduction.', 'Cardiac Biomarkers - NCLEX', false, 45, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Cardiac Biomarkers note, which statement about "NCLEX synthesis" is most accurate?', 'According to the Cardiac Biomarkers note, which statement about "NCLEX synthesis" is most accurate?', '[{"id": "a", "text": "CK-MB favored for reinfarction detection."}, {"id": "b", "text": "Myoglobin is more specific than troponin."}, {"id": "c", "text": "Myoglobin is best reinfarction marker."}, {"id": "d", "text": "BNP replaces troponin for MI confirmation."}]'::jsonb, '["a"]'::jsonb, 'Correct because NCLEX summary: Troponin is gold standard and longest-lasting, CK-MB best for reinfarction, BNP for HF dyspnea differentiation, myoglobin earliest but nonspecific. Match biomarker selection to the clinical question (diagnosis timing vs HF vs reinfarction).', 'Cardiac Biomarkers - NCLEX', false, 46, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Biomarker purpose" in Cardiac Biomarkers. Which statement is correct?', 'The nurse is reviewing "Biomarker purpose" in Cardiac Biomarkers. Which statement is correct?', '[{"id": "a", "text": "Troponin I normalizes within 12 hours."}, {"id": "b", "text": "Biomarkers rise when cardiac cells are damaged."}, {"id": "c", "text": "Cardiac injury does not alter biomarker levels."}, {"id": "d", "text": "Biomarkers only diagnose pulmonary embolism."}]'::jsonb, '["b"]'::jsonb, 'Correct because Cardiac biomarkers are blood proteins released after cardiac cell injury and are used for MI/HF diagnosis and stress assessment. Use biomarkers with clinical context to confirm or exclude acute cardiac injury.', 'Cardiac Biomarkers - NCLEX', false, 47, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Serial testing principle" in Cardiac Biomarkers?', 'Which clinical judgment is most accurate regarding "Serial testing principle" in Cardiac Biomarkers?', '[{"id": "a", "text": "Single value alone is insufficient for MI confirmation."}, {"id": "b", "text": "Serial testing is unnecessary in acute chest pain."}, {"id": "c", "text": "Serial rechecks are unnecessary when first value is borderline."}, {"id": "d", "text": "CK-BB comes from ventricular myocardium."}]'::jsonb, '["a"]'::jsonb, 'Correct because Serial values every 3–6 hours are needed, and a rise-and-fall pattern supports MI rather than one isolated elevation. Trend interpretation is safer than single-point interpretation.', 'Cardiac Biomarkers - NCLEX', false, 48, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Troponin priority" in Cardiac Biomarkers?', 'In rapid prioritization, which statement is most consistent with "Troponin priority" in Cardiac Biomarkers?', '[{"id": "a", "text": "Serial rechecks are unnecessary when first value is borderline."}, {"id": "b", "text": "BNP is unrelated to ventricular stretch."}, {"id": "c", "text": "Myoglobin is more specific than troponin."}, {"id": "d", "text": "Troponin has highest NCLEX priority in this section."}]'::jsonb, '["d"]'::jsonb, 'Correct because Troponin is the most specific and sensitive biomarker for MI and is the gold standard. Prioritize troponin trend review in suspected ACS workflows.', 'Cardiac Biomarkers - NCLEX', false, 49, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Troponin I kinetics" in Cardiac Biomarkers would the nurse recognize as correct?', 'Which conclusion about "Troponin I kinetics" in Cardiac Biomarkers would the nurse recognize as correct?', '[{"id": "a", "text": "Troponin I can stay elevated for 7–10 days."}, {"id": "b", "text": "Troponin I normalizes within 12 hours."}, {"id": "c", "text": "CK-BB is dominant in healthy blood."}, {"id": "d", "text": "CK-MB remains elevated for 14 days."}]'::jsonb, '["a"]'::jsonb, 'Correct because Troponin I normal is <0.04 ng/mL, rises 3–6h, peaks 12–24h, normalizes in 7–10 days. Use timing to detect delayed presentations and avoid false reassurance early.', 'Cardiac Biomarkers - NCLEX', false, 50, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Biomarker purpose" in Cardiac Biomarkers are correct? (Select all that apply)', 'Which statements about "Biomarker purpose" in Cardiac Biomarkers are correct? (Select all that apply)', '[{"id": "a", "text": "Biomarkers rise when cardiac cells are damaged."}, {"id": "b", "text": "Biomarkers only diagnose pulmonary embolism."}, {"id": "c", "text": "Cardiac injury does not alter biomarker levels."}, {"id": "d", "text": "They assist MI and HF evaluation."}, {"id": "e", "text": "They assess cardiac stress patterns."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Cardiac biomarkers are blood proteins released after cardiac cell injury and are used for MI/HF diagnosis and stress assessment.', 'Cardiac Biomarkers - NCLEX', true, 51, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Biomarkers, which findings or actions relate to "Serial testing principle"? (Select all that apply)', 'For Cardiac Biomarkers, which findings or actions relate to "Serial testing principle"? (Select all that apply)', '[{"id": "a", "text": "Single value alone is insufficient for MI confirmation."}, {"id": "b", "text": "Serial testing is unnecessary in acute chest pain."}, {"id": "c", "text": "One elevated value always confirms MI."}, {"id": "d", "text": "Serial q3–6h testing is listed."}, {"id": "e", "text": "Rise-and-fall pattern supports MI."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Serial values every 3–6 hours are needed, and a rise-and-fall pattern supports MI rather than one isolated elevation.', 'Cardiac Biomarkers - NCLEX', true, 52, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Troponin priority" in Cardiac Biomarkers? (Select all that apply)', 'The nurse is planning care. Which items apply to "Troponin priority" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Troponin has highest NCLEX priority in this section."}, {"id": "b", "text": "BNP is the gold standard for MI."}, {"id": "c", "text": "Myoglobin is more specific than troponin."}, {"id": "d", "text": "Troponin is both highly sensitive and specific in note."}, {"id": "e", "text": "Troponin is gold standard for MI."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Troponin is the most specific and sensitive biomarker for MI and is the gold standard.', 'Cardiac Biomarkers - NCLEX', true, 53, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Troponin I kinetics" in Cardiac Biomarkers? (Select all that apply)', 'Which of the following are consistent with "Troponin I kinetics" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Troponin I normalizes within 12 hours."}, {"id": "b", "text": "Troponin I peak occurs at 2 hours."}, {"id": "c", "text": "Troponin I rises at 3–6 hours."}, {"id": "d", "text": "Peak is 12–24 hours."}, {"id": "e", "text": "Troponin I can stay elevated for 7–10 days."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Troponin I normal is <0.04 ng/mL, rises 3–6h, peaks 12–24h, normalizes in 7–10 days.', 'Cardiac Biomarkers - NCLEX', true, 54, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Troponin T kinetics" in Cardiac Biomarkers? (Select all that apply)', 'During reassessment, which observations align with "Troponin T kinetics" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Duration extends up to 10–14 days."}, {"id": "b", "text": "Troponin T is gone by 24 hours."}, {"id": "c", "text": "Rise/peak times mirror early troponin kinetics."}, {"id": "d", "text": "Troponin T normal is <0.01 ng/mL."}, {"id": "e", "text": "Troponin T has no normal reference."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Troponin T normal is <0.01 ng/mL, rises 3–6h, peaks 12–24h, and normalizes over 10–14 days.', 'Cardiac Biomarkers - NCLEX', true, 55, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "hsTnT utility" in Cardiac Biomarkers are correct? (Select all that apply)', 'Which statements about "hsTnT utility" in Cardiac Biomarkers are correct? (Select all that apply)', '[{"id": "a", "text": "hsTnT is less sensitive than CK-MB."}, {"id": "b", "text": "hsTnT is used only for heart failure."}, {"id": "c", "text": "Useful in early subtle MI detection."}, {"id": "d", "text": "hsTnT detects smaller infarcts."}, {"id": "e", "text": "Sensitivity is higher than conventional threshold-only approach."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: High-sensitivity Troponin T can detect smaller myocardial infarctions.', 'Cardiac Biomarkers - NCLEX', true, 56, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Biomarkers, which findings or actions relate to "CK isoform composition"? (Select all that apply)', 'For Cardiac Biomarkers, which findings or actions relate to "CK isoform composition"? (Select all that apply)', '[{"id": "a", "text": "CK-MB comprises most CK."}, {"id": "b", "text": "CK-MB normal proportion is small."}, {"id": "c", "text": "CK-BB is dominant in healthy blood."}, {"id": "d", "text": "CK-MM is dominant fraction."}, {"id": "e", "text": "CK-BB is minimal in routine blood profile here."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: CK-MM is 96–100%, CK-MB is 0–5%, and CK-BB is about 0% in normal distribution listed.', 'Cardiac Biomarkers - NCLEX', true, 57, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "CK-MB timeline/use" in Cardiac Biomarkers? (Select all that apply)', 'The nurse is planning care. Which items apply to "CK-MB timeline/use" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "CK-MB remains elevated for 14 days."}, {"id": "b", "text": "Rise/peak/normalization windows are listed."}, {"id": "c", "text": "CK-MB has no role in reinfarction."}, {"id": "d", "text": "CK-MB normalizes faster than troponin."}, {"id": "e", "text": "CK-MB is useful for reinfarction detection."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: CK-MB rises 4–6h, peaks 18–24h, normalizes 48–72h, and is useful for MI and re-infarction detection.', 'Cardiac Biomarkers - NCLEX', true, 58, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "CK-MM limitation" in Cardiac Biomarkers? (Select all that apply)', 'Which of the following are consistent with "CK-MM limitation" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "CK-MM can rise in rhabdomyolysis."}, {"id": "b", "text": "CK-MM source is skeletal muscle."}, {"id": "c", "text": "CK-MM is most cardiac-specific marker."}, {"id": "d", "text": "CK-MM is not cardiac-specific."}, {"id": "e", "text": "CK-MM excludes muscle injury."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: CK-MM reflects skeletal muscle injury such as rhabdomyolysis and is not cardiac-specific.', 'Cardiac Biomarkers - NCLEX', true, 59, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "CK-BB limitation" in Cardiac Biomarkers? (Select all that apply)', 'During reassessment, which observations align with "CK-BB limitation" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "CK-BB is not cardiac marker of choice."}, {"id": "b", "text": "CK-BB comes from ventricular myocardium."}, {"id": "c", "text": "CK-BB is linked to brain/smooth muscle."}, {"id": "d", "text": "CK-BB is preferred biomarker for MI."}, {"id": "e", "text": "CK-BB can relate to bowel infarction in note."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: CK-BB is associated with brain/smooth muscle injury and is not used for cardiac monitoring.', 'Cardiac Biomarkers - NCLEX', true, 60, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "BNP physiology" in Cardiac Biomarkers are correct? (Select all that apply)', 'Which statements about "BNP physiology" in Cardiac Biomarkers are correct? (Select all that apply)', '[{"id": "a", "text": "BNP reflects wall stress."}, {"id": "b", "text": "Ventricular stretch triggers BNP release."}, {"id": "c", "text": "Volume overload increases BNP."}, {"id": "d", "text": "BNP is unrelated to ventricular stretch."}, {"id": "e", "text": "BNP rises only from skeletal injury."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: BNP is released from ventricular myocytes when stretched by volume overload.', 'Cardiac Biomarkers - NCLEX', true, 61, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Biomarkers, which findings or actions relate to "BNP ranges"? (Select all that apply)', 'For Cardiac Biomarkers, which findings or actions relate to "BNP ranges"? (Select all that apply)', '[{"id": "a", "text": "100–400 suggests possible HF."}, {"id": "b", "text": "BNP <100 is normal."}, {"id": "c", "text": ">400 suggests likely HF exacerbation."}, {"id": "d", "text": "BNP >400 excludes HF."}, {"id": "e", "text": "BNP <20 defines severe HF."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: BNP normal is <100 pg/mL; 100–400 possible HF; >400 likely HF exacerbation.', 'Cardiac Biomarkers - NCLEX', true, 62, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "BNP clinical use" in Cardiac Biomarkers? (Select all that apply)', 'The nurse is planning care. Which items apply to "BNP clinical use" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "BNP helps guide diuretic and discharge decisions."}, {"id": "b", "text": "BNP confirms MI infarct size directly."}, {"id": "c", "text": "Higher BNP correlates with worse prognosis."}, {"id": "d", "text": "BNP has no prognostic value."}, {"id": "e", "text": "BNP can separate cardiac vs pulmonary dyspnea causes."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: BNP helps differentiate cardiac from pulmonary dyspnea, guides diuresis/discharge, and higher BNP suggests worse prognosis.', 'Cardiac Biomarkers - NCLEX', true, 63, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "BNP not MI marker" in Cardiac Biomarkers? (Select all that apply)', 'Which of the following are consistent with "BNP not MI marker" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "BNP indicates volume overload, not infarction specificity."}, {"id": "b", "text": "BNP is the most specific MI marker."}, {"id": "c", "text": "Troponin remains MI marker priority."}, {"id": "d", "text": "BNP rise alone proves STEMI."}, {"id": "e", "text": "BNP is HF-oriented biomarker in note."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: The note explicitly states BNP does not indicate MI; it indicates fluid overload/heart failure context.', 'Cardiac Biomarkers - NCLEX', true, 64, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "NT-proBNP reference" in Cardiac Biomarkers? (Select all that apply)', 'During reassessment, which observations align with "NT-proBNP reference" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "NT-proBNP reference <300 is listed."}, {"id": "b", "text": "Longer half-life is noted."}, {"id": "c", "text": "NT-proBNP normal is <30."}, {"id": "d", "text": "NT-proBNP interpretation differs from BNP thresholds."}, {"id": "e", "text": "NT-proBNP has shorter half-life than BNP."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: NT-proBNP normal is listed as <300 pg/mL and has longer half-life.', 'Cardiac Biomarkers - NCLEX', true, 65, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Myoglobin kinetics" in Cardiac Biomarkers are correct? (Select all that apply)', 'Which statements about "Myoglobin kinetics" in Cardiac Biomarkers are correct? (Select all that apply)', '[{"id": "a", "text": "Myoglobin rises after troponin peak."}, {"id": "b", "text": "Myoglobin stays elevated 10 days."}, {"id": "c", "text": "Rise occurs 1–3 hours."}, {"id": "d", "text": "Myoglobin is earliest riser in note."}, {"id": "e", "text": "Normalization occurs by about 24 hours."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Myoglobin rises first at 1–3h after MI but normalizes quickly within 24h.', 'Cardiac Biomarkers - NCLEX', true, 66, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Biomarkers, which findings or actions relate to "Myoglobin limitation/use"? (Select all that apply)', 'For Cardiac Biomarkers, which findings or actions relate to "Myoglobin limitation/use"? (Select all that apply)', '[{"id": "a", "text": "Specificity is limited."}, {"id": "b", "text": "Myoglobin comes from skeletal and cardiac muscle."}, {"id": "c", "text": "Myoglobin alone confirms MI."}, {"id": "d", "text": "Myoglobin is highly cardiac-specific."}, {"id": "e", "text": "Normal early myoglobin lowers immediate MI likelihood."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Myoglobin is not cardiac-specific and is used mainly for early rule-out when normal at around 3h.', 'Cardiac Biomarkers - NCLEX', true, 67, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Timeline comparison" in Cardiac Biomarkers? (Select all that apply)', 'The nurse is planning care. Which items apply to "Timeline comparison" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Myoglobin rises earliest."}, {"id": "b", "text": "Troponin clears before CK-MB."}, {"id": "c", "text": "Myoglobin persists longest."}, {"id": "d", "text": "Troponin persists the longest."}, {"id": "e", "text": "CK-MB clears before troponin."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Timeline summary: myoglobin earliest/shortest, CK-MB intermediate, troponin longest duration.', 'Cardiac Biomarkers - NCLEX', true, 68, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "BUN/creatinine interpretation" in Cardiac Biomarkers? (Select all that apply)', 'Which of the following are consistent with "BUN/creatinine interpretation" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Normal creatinine excludes dehydration."}, {"id": "b", "text": "High BUN + high creatinine suggests renal impairment."}, {"id": "c", "text": "High BUN with normal creatinine proves MI."}, {"id": "d", "text": "BUN normal range 7–20 is listed."}, {"id": "e", "text": "Creatinine normal 0.6–1.2 is listed."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: BUN 7–20 and creatinine 0.6–1.2 are listed normal; high BUN with normal creatinine suggests dehydration, while both high suggest renal impairment.', 'Cardiac Biomarkers - NCLEX', true, 69, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Low-output renal effect" in Cardiac Biomarkers? (Select all that apply)', 'During reassessment, which observations align with "Low-output renal effect" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "BUN/Cr are unrelated to hemodynamics."}, {"id": "b", "text": "Cardiorenal relationship is explicitly noted."}, {"id": "c", "text": "Renal perfusion is unaffected by cardiac output."}, {"id": "d", "text": "Low cardiac output can impair renal perfusion."}, {"id": "e", "text": "Renal markers may rise in low-output states."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Reduced cardiac output can increase BUN/creatinine due to renal hypoperfusion.', 'Cardiac Biomarkers - NCLEX', true, 70, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Lactate and ABG significance" in Cardiac Biomarkers are correct? (Select all that apply)', 'Which statements about "Lactate and ABG significance" in Cardiac Biomarkers are correct? (Select all that apply)', '[{"id": "a", "text": "Lactate >2 indicates hypoperfusion in note."}, {"id": "b", "text": "Metabolic acidosis can occur in shock/MI."}, {"id": "c", "text": "ABG is irrelevant in shock."}, {"id": "d", "text": "ABG/lactate assist shock severity assessment."}, {"id": "e", "text": "Lactate <0.2 is the shock threshold."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Shock/MI may show metabolic acidosis; lactate >2 mmol/L indicates tissue hypoperfusion and helps gauge shock severity.', 'Cardiac Biomarkers - NCLEX', true, 71, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Biomarkers, which findings or actions relate to "Lipid panel targets"? (Select all that apply)', 'For Cardiac Biomarkers, which findings or actions relate to "Lipid panel targets"? (Select all that apply)', '[{"id": "a", "text": "HDL >60 is protective per note."}, {"id": "b", "text": "LDL <70 is listed for high-risk."}, {"id": "c", "text": "LDL >160 is optimal in high-risk."}, {"id": "d", "text": "Total cholesterol target <200 is listed."}, {"id": "e", "text": "HDL under 20 is protective."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Desired lipids listed are total cholesterol <200, LDL <70 in high-risk patients, and HDL >60 as protective.', 'Cardiac Biomarkers - NCLEX', true, 72, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "NCLEX synthesis" in Cardiac Biomarkers? (Select all that apply)', 'The nurse is planning care. Which items apply to "NCLEX synthesis" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "BNP replaces troponin for MI confirmation."}, {"id": "b", "text": "Troponin is top MI marker in NCLEX summary."}, {"id": "c", "text": "Myoglobin is best reinfarction marker."}, {"id": "d", "text": "CK-MB favored for reinfarction detection."}, {"id": "e", "text": "BNP and myoglobin have distinct non-overlapping roles."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: NCLEX summary: Troponin is gold standard and longest-lasting, CK-MB best for reinfarction, BNP for HF dyspnea differentiation, myoglobin earliest but nonspecific.', 'Cardiac Biomarkers - NCLEX', true, 73, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Biomarker purpose" in Cardiac Biomarkers? (Select all that apply)', 'Which of the following are consistent with "Biomarker purpose" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "They assess cardiac stress patterns."}, {"id": "b", "text": "They assist MI and HF evaluation."}, {"id": "c", "text": "Cardiac injury does not alter biomarker levels."}, {"id": "d", "text": "Biomarkers only diagnose pulmonary embolism."}, {"id": "e", "text": "Biomarkers rise when cardiac cells are damaged."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Cardiac biomarkers are blood proteins released after cardiac cell injury and are used for MI/HF diagnosis and stress assessment.', 'Cardiac Biomarkers - NCLEX', true, 74, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Serial testing principle" in Cardiac Biomarkers? (Select all that apply)', 'During reassessment, which observations align with "Serial testing principle" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "One elevated value always confirms MI."}, {"id": "b", "text": "Rise-and-fall pattern supports MI."}, {"id": "c", "text": "Single value alone is insufficient for MI confirmation."}, {"id": "d", "text": "Serial q3–6h testing is listed."}, {"id": "e", "text": "Serial testing is unnecessary in acute chest pain."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Serial values every 3–6 hours are needed, and a rise-and-fall pattern supports MI rather than one isolated elevation.', 'Cardiac Biomarkers - NCLEX', true, 75, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Troponin priority" in Cardiac Biomarkers are correct? (Select all that apply)', 'Which statements about "Troponin priority" in Cardiac Biomarkers are correct? (Select all that apply)', '[{"id": "a", "text": "Troponin is gold standard for MI."}, {"id": "b", "text": "BNP is the gold standard for MI."}, {"id": "c", "text": "Myoglobin is more specific than troponin."}, {"id": "d", "text": "Troponin has highest NCLEX priority in this section."}, {"id": "e", "text": "Troponin is both highly sensitive and specific in note."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Troponin is the most specific and sensitive biomarker for MI and is the gold standard.', 'Cardiac Biomarkers - NCLEX', true, 76, 1, true);
