  VALUES (v_test_id, v_topic_id, 'Which statements about "CK-MB timeline/use" in Cardiac Biomarkers are correct? (Select all that apply)', 'Which statements about "CK-MB timeline/use" in Cardiac Biomarkers are correct? (Select all that apply)', '[{"id": "a", "text": "Rise/peak/normalization windows are listed."}, {"id": "b", "text": "CK-MB has no role in reinfarction."}, {"id": "c", "text": "CK-MB normalizes faster than troponin."}, {"id": "d", "text": "CK-MB remains elevated for 14 days."}, {"id": "e", "text": "CK-MB is useful for reinfarction detection."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: CK-MB rises 4–6h, peaks 18–24h, normalizes 48–72h, and is useful for MI and re-infarction detection.', 'Cardiac Biomarkers - NCLEX', true, 81, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Biomarkers, which findings or actions relate to "CK-MM limitation"? (Select all that apply)', 'For Cardiac Biomarkers, which findings or actions relate to "CK-MM limitation"? (Select all that apply)', '[{"id": "a", "text": "CK-MM is not cardiac-specific."}, {"id": "b", "text": "CK-MM source is skeletal muscle."}, {"id": "c", "text": "CK-MM excludes muscle injury."}, {"id": "d", "text": "CK-MM is most cardiac-specific marker."}, {"id": "e", "text": "CK-MM can rise in rhabdomyolysis."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: CK-MM reflects skeletal muscle injury such as rhabdomyolysis and is not cardiac-specific.', 'Cardiac Biomarkers - NCLEX', true, 82, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "CK-BB limitation" in Cardiac Biomarkers? (Select all that apply)', 'The nurse is planning care. Which items apply to "CK-BB limitation" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "CK-BB is not cardiac marker of choice."}, {"id": "b", "text": "CK-BB comes from ventricular myocardium."}, {"id": "c", "text": "CK-BB can relate to bowel infarction in note."}, {"id": "d", "text": "CK-BB is linked to brain/smooth muscle."}, {"id": "e", "text": "CK-BB is preferred biomarker for MI."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: CK-BB is associated with brain/smooth muscle injury and is not used for cardiac monitoring.', 'Cardiac Biomarkers - NCLEX', true, 83, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "BNP physiology" in Cardiac Biomarkers? (Select all that apply)', 'Which of the following are consistent with "BNP physiology" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "BNP is unrelated to ventricular stretch."}, {"id": "b", "text": "Ventricular stretch triggers BNP release."}, {"id": "c", "text": "BNP rises only from skeletal injury."}, {"id": "d", "text": "Volume overload increases BNP."}, {"id": "e", "text": "BNP reflects wall stress."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: BNP is released from ventricular myocytes when stretched by volume overload.', 'Cardiac Biomarkers - NCLEX', true, 84, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "BNP ranges" in Cardiac Biomarkers? (Select all that apply)', 'During reassessment, which observations align with "BNP ranges" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "BNP <20 defines severe HF."}, {"id": "b", "text": "100–400 suggests possible HF."}, {"id": "c", "text": ">400 suggests likely HF exacerbation."}, {"id": "d", "text": "BNP >400 excludes HF."}, {"id": "e", "text": "BNP <100 is normal."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: BNP normal is <100 pg/mL; 100–400 possible HF; >400 likely HF exacerbation.', 'Cardiac Biomarkers - NCLEX', true, 85, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "BNP clinical use" in Cardiac Biomarkers are correct? (Select all that apply)', 'Which statements about "BNP clinical use" in Cardiac Biomarkers are correct? (Select all that apply)', '[{"id": "a", "text": "BNP has no prognostic value."}, {"id": "b", "text": "Higher BNP correlates with worse prognosis."}, {"id": "c", "text": "BNP can separate cardiac vs pulmonary dyspnea causes."}, {"id": "d", "text": "BNP confirms MI infarct size directly."}, {"id": "e", "text": "BNP helps guide diuretic and discharge decisions."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: BNP helps differentiate cardiac from pulmonary dyspnea, guides diuresis/discharge, and higher BNP suggests worse prognosis.', 'Cardiac Biomarkers - NCLEX', true, 86, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Biomarkers, which findings or actions relate to "BNP not MI marker"? (Select all that apply)', 'For Cardiac Biomarkers, which findings or actions relate to "BNP not MI marker"? (Select all that apply)', '[{"id": "a", "text": "BNP rise alone proves STEMI."}, {"id": "b", "text": "BNP is HF-oriented biomarker in note."}, {"id": "c", "text": "BNP indicates volume overload, not infarction specificity."}, {"id": "d", "text": "BNP is the most specific MI marker."}, {"id": "e", "text": "Troponin remains MI marker priority."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: The note explicitly states BNP does not indicate MI; it indicates fluid overload/heart failure context.', 'Cardiac Biomarkers - NCLEX', true, 87, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "NT-proBNP reference" in Cardiac Biomarkers? (Select all that apply)', 'The nurse is planning care. Which items apply to "NT-proBNP reference" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Longer half-life is noted."}, {"id": "b", "text": "NT-proBNP reference <300 is listed."}, {"id": "c", "text": "NT-proBNP interpretation differs from BNP thresholds."}, {"id": "d", "text": "NT-proBNP normal is <30."}, {"id": "e", "text": "NT-proBNP has shorter half-life than BNP."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: NT-proBNP normal is listed as <300 pg/mL and has longer half-life.', 'Cardiac Biomarkers - NCLEX', true, 88, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Myoglobin kinetics" in Cardiac Biomarkers? (Select all that apply)', 'Which of the following are consistent with "Myoglobin kinetics" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Myoglobin is earliest riser in note."}, {"id": "b", "text": "Myoglobin stays elevated 10 days."}, {"id": "c", "text": "Rise occurs 1–3 hours."}, {"id": "d", "text": "Normalization occurs by about 24 hours."}, {"id": "e", "text": "Myoglobin rises after troponin peak."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Myoglobin rises first at 1–3h after MI but normalizes quickly within 24h.', 'Cardiac Biomarkers - NCLEX', true, 89, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Myoglobin limitation/use" in Cardiac Biomarkers? (Select all that apply)', 'During reassessment, which observations align with "Myoglobin limitation/use" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Myoglobin is highly cardiac-specific."}, {"id": "b", "text": "Normal early myoglobin lowers immediate MI likelihood."}, {"id": "c", "text": "Myoglobin alone confirms MI."}, {"id": "d", "text": "Specificity is limited."}, {"id": "e", "text": "Myoglobin comes from skeletal and cardiac muscle."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Myoglobin is not cardiac-specific and is used mainly for early rule-out when normal at around 3h.', 'Cardiac Biomarkers - NCLEX', true, 90, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Timeline comparison" in Cardiac Biomarkers are correct? (Select all that apply)', 'Which statements about "Timeline comparison" in Cardiac Biomarkers are correct? (Select all that apply)', '[{"id": "a", "text": "CK-MB clears before troponin."}, {"id": "b", "text": "Troponin persists the longest."}, {"id": "c", "text": "Myoglobin persists longest."}, {"id": "d", "text": "Myoglobin rises earliest."}, {"id": "e", "text": "Troponin clears before CK-MB."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Timeline summary: myoglobin earliest/shortest, CK-MB intermediate, troponin longest duration.', 'Cardiac Biomarkers - NCLEX', true, 91, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Biomarkers, which findings or actions relate to "BUN/creatinine interpretation"? (Select all that apply)', 'For Cardiac Biomarkers, which findings or actions relate to "BUN/creatinine interpretation"? (Select all that apply)', '[{"id": "a", "text": "Normal creatinine excludes dehydration."}, {"id": "b", "text": "BUN normal range 7–20 is listed."}, {"id": "c", "text": "High BUN + high creatinine suggests renal impairment."}, {"id": "d", "text": "Creatinine normal 0.6–1.2 is listed."}, {"id": "e", "text": "High BUN with normal creatinine proves MI."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: BUN 7–20 and creatinine 0.6–1.2 are listed normal; high BUN with normal creatinine suggests dehydration, while both high suggest renal impairment.', 'Cardiac Biomarkers - NCLEX', true, 92, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Low-output renal effect" in Cardiac Biomarkers? (Select all that apply)', 'The nurse is planning care. Which items apply to "Low-output renal effect" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "BUN/Cr are unrelated to hemodynamics."}, {"id": "b", "text": "Renal markers may rise in low-output states."}, {"id": "c", "text": "Low cardiac output can impair renal perfusion."}, {"id": "d", "text": "Cardiorenal relationship is explicitly noted."}, {"id": "e", "text": "Renal perfusion is unaffected by cardiac output."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Reduced cardiac output can increase BUN/creatinine due to renal hypoperfusion.', 'Cardiac Biomarkers - NCLEX', true, 93, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Lactate and ABG significance" in Cardiac Biomarkers? (Select all that apply)', 'Which of the following are consistent with "Lactate and ABG significance" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "ABG is irrelevant in shock."}, {"id": "b", "text": "Lactate <0.2 is the shock threshold."}, {"id": "c", "text": "Lactate >2 indicates hypoperfusion in note."}, {"id": "d", "text": "Metabolic acidosis can occur in shock/MI."}, {"id": "e", "text": "ABG/lactate assist shock severity assessment."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Shock/MI may show metabolic acidosis; lactate >2 mmol/L indicates tissue hypoperfusion and helps gauge shock severity.', 'Cardiac Biomarkers - NCLEX', true, 94, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Lipid panel targets" in Cardiac Biomarkers? (Select all that apply)', 'During reassessment, which observations align with "Lipid panel targets" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Total cholesterol target <200 is listed."}, {"id": "b", "text": "HDL under 20 is protective."}, {"id": "c", "text": "LDL >160 is optimal in high-risk."}, {"id": "d", "text": "LDL <70 is listed for high-risk."}, {"id": "e", "text": "HDL >60 is protective per note."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Desired lipids listed are total cholesterol <200, LDL <70 in high-risk patients, and HDL >60 as protective.', 'Cardiac Biomarkers - NCLEX', true, 95, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "NCLEX synthesis" in Cardiac Biomarkers are correct? (Select all that apply)', 'Which statements about "NCLEX synthesis" in Cardiac Biomarkers are correct? (Select all that apply)', '[{"id": "a", "text": "BNP and myoglobin have distinct non-overlapping roles."}, {"id": "b", "text": "Myoglobin is best reinfarction marker."}, {"id": "c", "text": "CK-MB favored for reinfarction detection."}, {"id": "d", "text": "BNP replaces troponin for MI confirmation."}, {"id": "e", "text": "Troponin is top MI marker in NCLEX summary."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: NCLEX summary: Troponin is gold standard and longest-lasting, CK-MB best for reinfarction, BNP for HF dyspnea differentiation, myoglobin earliest but nonspecific.', 'Cardiac Biomarkers - NCLEX', true, 96, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Biomarkers, which findings or actions relate to "Biomarker purpose"? (Select all that apply)', 'For Cardiac Biomarkers, which findings or actions relate to "Biomarker purpose"? (Select all that apply)', '[{"id": "a", "text": "Biomarkers only diagnose pulmonary embolism."}, {"id": "b", "text": "They assist MI and HF evaluation."}, {"id": "c", "text": "Cardiac injury does not alter biomarker levels."}, {"id": "d", "text": "Biomarkers rise when cardiac cells are damaged."}, {"id": "e", "text": "They assess cardiac stress patterns."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Cardiac biomarkers are blood proteins released after cardiac cell injury and are used for MI/HF diagnosis and stress assessment.', 'Cardiac Biomarkers - NCLEX', true, 97, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Serial testing principle" in Cardiac Biomarkers? (Select all that apply)', 'The nurse is planning care. Which items apply to "Serial testing principle" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Rise-and-fall pattern supports MI."}, {"id": "b", "text": "Single value alone is insufficient for MI confirmation."}, {"id": "c", "text": "Serial q3–6h testing is listed."}, {"id": "d", "text": "One elevated value always confirms MI."}, {"id": "e", "text": "Serial testing is unnecessary in acute chest pain."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Serial values every 3–6 hours are needed, and a rise-and-fall pattern supports MI rather than one isolated elevation.', 'Cardiac Biomarkers - NCLEX', true, 98, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Troponin priority" in Cardiac Biomarkers? (Select all that apply)', 'Which of the following are consistent with "Troponin priority" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Troponin is both highly sensitive and specific in note."}, {"id": "b", "text": "Troponin has highest NCLEX priority in this section."}, {"id": "c", "text": "Troponin is gold standard for MI."}, {"id": "d", "text": "BNP is the gold standard for MI."}, {"id": "e", "text": "Myoglobin is more specific than troponin."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Troponin is the most specific and sensitive biomarker for MI and is the gold standard.', 'Cardiac Biomarkers - NCLEX', true, 99, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Troponin I kinetics" in Cardiac Biomarkers? (Select all that apply)', 'During reassessment, which observations align with "Troponin I kinetics" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Peak is 12–24 hours."}, {"id": "b", "text": "Troponin I can stay elevated for 7–10 days."}, {"id": "c", "text": "Troponin I normalizes within 12 hours."}, {"id": "d", "text": "Troponin I peak occurs at 2 hours."}, {"id": "e", "text": "Troponin I rises at 3–6 hours."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Troponin I normal is <0.04 ng/mL, rises 3–6h, peaks 12–24h, normalizes in 7–10 days.', 'Cardiac Biomarkers - NCLEX', true, 100, 1, true);
